BEGIN;
INSERT INTO public.admin_users(id,email,password_hash,role,is_active) VALUES('f8300000-0000-4000-8000-000000000001','newsletter-sender@example.test','test-only','admin',true);
INSERT INTO public.admin_sessions(id,admin_user_id,token_hash) VALUES('f8300000-0000-4000-8000-000000000002','f8300000-0000-4000-8000-000000000001',repeat('1',64)),('f8300000-0000-4000-8000-000000000003','f8300000-0000-4000-8000-000000000001',repeat('2',64));
DO $$ DECLARE actor uuid:='f8300000-0000-4000-8000-000000000001';sid uuid:='f8300000-0000-4000-8000-000000000002';t uuid;s uuid;late uuid;c uuid;review uuid;v jsonb;BEGIN
 IF has_function_privilege('authenticated','public.advance_newsletter_campaigns()','EXECUTE') OR has_table_privilege('anon','public.newsletter_campaign_recipients','SELECT') THEN RAISE EXCEPTION 'Browser campaign delivery access';END IF;
 INSERT INTO public.admin_teams(name,slug,created_by) VALUES('Fictional campaign scope','fictional-campaign-scope',actor) RETURNING id INTO t;
 INSERT INTO public.newsletter_subscribers(email,name,team_id,state,is_active,consent_at,confirmed_at) VALUES('fictional-campaign-first@example.test','First',t,'active',true,now(),now()) RETURNING id INTO s;
 INSERT INTO public.newsletter_subscribers(email,name,team_id,state,is_active,consent_at,confirmed_at) VALUES('fictional-campaign-second@example.test','Second',t,'active',true,now(),now());
 INSERT INTO public.newsletter_subscribers(email,name,team_id,state,is_active,consent_at) VALUES('fictional-campaign-pending@example.test','Pending',t,'pending',false,now());
 INSERT INTO public.newsletter_subscribers(email,name,team_id,state,is_active,consent_at,confirmed_at,suppressed_at,suppression_reason) VALUES('fictional-campaign-suppressed@example.test','Suppressed',t,'active',true,now(),now(),now(),'complaint');
 v:=public.mutate_newsletter_record(actor,sid,'campaigns',NULL,'create',NULL,jsonb_build_object('teamId',t,'record',jsonb_build_object('subject','Fictional test campaign','content','Fixture only','audience','all','recipientIds','[]'::jsonb)),repeat('1',64),repeat('2',64),gen_random_uuid());c:=(v->>'id')::uuid;
 v:=public.review_newsletter_send(actor,sid,c,1,repeat('a',64),gen_random_uuid());review:=(v->>'reviewId')::uuid;
 IF(v->>'count')::integer<>2 THEN RAISE EXCEPTION 'Pending or suppressed recipients included';END IF;
 BEGIN PERFORM public.commit_newsletter_send(actor,'f8300000-0000-4000-8000-000000000003',c,review,repeat('a',64),'test-only','SEND 2',NULL,repeat('3',64),repeat('2',64),gen_random_uuid());RAISE EXCEPTION 'Foreign session review';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NEWSLETTER_REVIEW_EXPIRED' THEN RAISE;END IF;END;
 BEGIN PERFORM public.commit_newsletter_send(actor,sid,c,review,repeat('a',64),'wrong','SEND 2',NULL,repeat('3',64),repeat('2',64),gen_random_uuid());RAISE EXCEPTION 'Unchecked sender password';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NOT_FOUND' THEN RAISE;END IF;END;
 INSERT INTO public.newsletter_subscribers(email,name,team_id,state,is_active,consent_at,confirmed_at) VALUES('fictional-campaign-new@example.test','New',t,'active',true,now(),now()) RETURNING id INTO late;
 BEGIN PERFORM public.commit_newsletter_send(actor,sid,c,review,repeat('a',64),'test-only','SEND 2',NULL,repeat('3',64),repeat('2',64),gen_random_uuid());RAISE EXCEPTION 'Changed audience accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'AUDIENCE_CHANGED' THEN RAISE;END IF;END;
 v:=public.review_newsletter_send(actor,sid,c,1,repeat('b',64),gen_random_uuid());review:=(v->>'reviewId')::uuid;
 v:=public.commit_newsletter_send(actor,sid,c,review,repeat('b',64),'test-only','SEND 3',NULL,repeat('3',64),repeat('2',64),gen_random_uuid());
 v:=public.commit_newsletter_send(actor,sid,c,review,repeat('b',64),'test-only','SEND 3',NULL,repeat('3',64),repeat('2',64),gen_random_uuid());
 IF(SELECT count(*) FROM public.newsletter_campaign_recipients WHERE campaign_id=c)<>3 THEN RAISE EXCEPTION 'Approval retry duplicated snapshot';END IF;
 BEGIN UPDATE public.newsletter_campaigns SET content='Changed after approval' WHERE id=c;RAISE EXCEPTION 'Approved content rewritten';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NEWSLETTER_LOCKED' THEN RAISE;END IF;END;
 INSERT INTO public.newsletter_subscribers(email,name,team_id,state,is_active,consent_at,confirmed_at) VALUES('fictional-campaign-too-late@example.test','Too late',t,'active',true,now(),now());
 v:=public.advance_newsletter_campaigns();
 IF(SELECT count(*) FROM public.delivery_jobs WHERE kind='newsletter_campaign' AND payload->>'campaignId'=c::text)<>3 THEN RAISE EXCEPTION 'Scheduled start did not preserve frozen audience';END IF;
 v:=public.advance_newsletter_campaigns();
 IF(SELECT count(*) FROM public.delivery_jobs WHERE kind='newsletter_campaign' AND payload->>'campaignId'=c::text)<>3 THEN RAISE EXCEPTION 'Scheduler duplicate send';END IF;
 v:=public.cancel_newsletter_send(actor,sid,c,3,'test-only',gen_random_uuid());
 IF(SELECT status FROM public.newsletter_campaigns WHERE id=c)<>'cancelled' OR EXISTS(SELECT 1 FROM public.newsletter_campaign_recipients WHERE campaign_id=c AND state='queued') OR EXISTS(SELECT 1 FROM public.delivery_jobs WHERE kind='newsletter_campaign' AND payload->>'campaignId'=c::text AND state='pending') THEN RAISE EXCEPTION 'Cancellation did not fence queued sends';END IF;
 BEGIN PERFORM public.review_newsletter_send(actor,sid,c,4,repeat('c',64),gen_random_uuid());RAISE EXCEPTION 'Campaign sent twice';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NEWSLETTER_LOCKED' THEN RAISE;END IF;END;
END $$;
ROLLBACK;
